import type { ToolPage } from '../toolPage.ts'

// Sources: caliper README, docs/parity.md, docs/storybook-parity.md, the integration READMEs, the shadcn snapshot, and PRs 154, 172, 197–202.
// The parity table is the measured 0.4.0 baseline (2026-10-23), not a claim about the current open work.
export const caliper: ToolPage = {
  installInHeroOnly: true,
  whyLayout: 'stack',
  why: [
    'Fast prop docs miss inherited types. Thorough ones make Storybook wait for a full TypeScript program.',
    'Caliper reads source and package types with OXC and Rust, then gives Storybook the props, defaults and descriptions it needs.',
    'Works with Storybook 10 and 11 today. The next alpha adds on-demand lookup and an experimental TypeScript 7.1 opt-in.',
  ],
  outcome: {
    title: 'Types in. Controls out.',
    description: 'One real Button from Caliper’s Storybook 11 integration test.',
    content: {
      caption: 'Selected argTypes returned for the Button fixture',
      columns: ['prop', 'type / choices', 'required', 'default', 'description'],
      rows: [
        ['variant', 'primary, secondary, ghost', 'no', '"primary"', 'Visual weight.'],
        ['label', 'string', 'yes', '—', 'The text on the button.'],
      ],
    },
    note: {
      label: 'source',
      links: [
        {
          label: 'Button fixture',
          href: 'https://github.com/orin-dx/caliper/blob/main/packages/storybook/tests/fixtures/project/src/components/Button.tsx',
        },
        {
          label: 'Storybook test',
          href: 'https://github.com/orin-dx/caliper/blob/main/packages/storybook/tests/integration/provider.integration.test.ts',
        },
      ],
    },
  },
  samples: {
    title: 'Choose your setup',
    description: 'The hero command installs the CLI. For Storybook, use the package for your version.',
    content: [
      {
        caption: 'Storybook 11: install the addon and use its docgen provider',
        language: 'tsx',
        lineNumbers: true,
        code: `// npm install --save-dev caliper-docgen-storybook
// .storybook/main.ts
export default {
  framework: '@storybook/react-vite',
  addons: [
    { name: 'caliper-docgen-storybook', options: { srcDirs: ['src'] } },
  ],
}`,
      },
      {
        caption: 'Storybook 10: inject __docgenInfo through Vite',
        language: 'tsx',
        lineNumbers: true,
        code: `// npm install --save-dev caliper-docgen-vite-plugin
// .storybook/main.ts
import { caliperDocgen } from 'caliper-docgen-vite-plugin'

export default {
  framework: '@storybook/react-vite',
  typescript: { reactDocgen: false },
  viteFinal: (config) => ({
    ...config,
    plugins: [...(config.plugins ?? []), caliperDocgen({
      srcDirs: ['src'],
      loadDependencies: true,
      injectDocgenInfo: true,
    })],
  }),
}`,
      },
      {
        caption: 'CLI: inspect one component or check the project in CI',
        language: 'bash',
        code: `npx caliper-docgen inspect Button --src src
npx caliper-docgen check --src src`,
      },
    ],
  },
  workflow: {
    title: 'Save. See updated props.',
    description: 'Caliper keeps a session open while you work.',
    content: [
      {
        title: 'Storybook 10',
        items: ['The Vite plugin updates docs for changed components while React Fast Refresh keeps working.'],
      },
      {
        title: 'Storybook 11',
        items: [
          'Each docgen request sees saved edits. If Caliper cannot fully describe a component, Storybook’s own docgen can take over.',
          'The next alpha resolves a component when its story asks for it, instead of doing every component up front.',
        ],
      },
    ],
    evidence: {
      text: 'Early source run: 129 React Spectrum stories took 0.63 s of addon request time, 4 ms at the median and 150 ms for the first request. October 24; not browser rendering or a 0.5.0 package result.',
      label: 'How we measure dev mode',
      href: '/tools/caliper/measurement/',
    },
  },
  figures: {
    title: 'How it stacks up',
    description:
      'The RDT (react-docgen-typescript) results use five installed libraries. The three-tool race uses 21 fixtures. Both ran in October 2026; newer work needs a rerun.',
    note: {
      label: 'source',
      links: [
        { label: 'Three-tool benchmark', href: 'https://github.com/orin-dx/caliper/blob/main/README.md' },
        { label: 'Five-library parity', href: 'https://github.com/orin-dx/caliper/blob/main/docs/parity.md' },
      ],
    },
    content: [
      {
        value: '99.7%',
        label: 'of RDT’s non-React props found on matched Mantine and Spectrum components',
        method: '0.4.0 parity baseline, installed dependencies, 2026-10-23',
      },
      {
        value: '28×',
        label: 'faster than RDT at the median of five installed libraries',
        method: '0.4.0 parity baseline, Caliper process start included; RDT timed in-process',
      },
    ],
  },
  race: {
    title: 'Cold run through one Node harness',
    method: '21 fixture libraries, Apple M5 Max, five runs, October 2026. About 0.32 s is shared harness startup.',
    bars: [
      { label: 'Caliper', text: '0.38 s', value: 0.38, ours: true },
      { label: 'react-docgen', text: '0.52 s', value: 0.52 },
      { label: 'RDT', text: '4.9 s', value: 4.9 },
    ],
  },
  deepDives: {
    title: 'Go deeper',
    description: 'The chart is the short version. The details are here when you need them.',
    content: [
      {
        title: 'Prop parity',
        eyebrow: '01 / the output',
        preview: '99.7%',
        cue: 'RDT props found on matched Mantine and Spectrum components',
        text: 'Explore all five libraries, the misses and the types RDT gets wrong too.',
        href: '/tools/caliper/parity/',
      },
      {
        title: 'How we measure',
        eyebrow: '02 / the method',
        preview: '3 clocks',
        cue: 'Cold run · installed libraries · Storybook requests',
        text: 'See the inputs, timing boundaries and dev-mode results behind each claim.',
        href: '/tools/caliper/measurement/',
      },
    ],
  },
  limits: [
    'Install 0.5.0 now. On-demand Storybook lookup lands in the next alpha.',
    'Coverage varies by library. shadcn/ui and Ant Design have the largest measured prop gaps; newer fixes need a rerun.',
    'TypeScript 7.1 is an experimental CLI opt-in. It checks exported function components; Storybook support is still ahead.',
    'Dependency loading is opt-in in 0.5.0. Use --load-dependencies in the CLI or loadDependencies: true in the Vite plugin; the Storybook 11 addon gets the option next alpha.',
    'Storybook 11 can fall back to its own docgen. On Storybook 10, turn off its transform to keep Caliper’s output.',
    'FSL-1.1-MIT licensed. Each release becomes MIT after two years.',
  ],
  features: {
    title: 'What you get',
    description: 'Useful prop docs in Storybook, in a build or from the command line.',
    layout: 'editorial',
    content: [
      {
        title: 'Richer props',
        items: [
          'Names, types, defaults and descriptions, with JSDoc close by.',
          'Inherited HTML props and types from installed packages.',
          'Literal choices from CVA, Tailwind Variants and Panda recipes. Some shadcn variants stay specific where RDT prints string.',
        ],
      },
      {
        title: 'Keep the table useful',
        items: [
          'Choose a curated, full or empty set of inherited HTML props.',
          'Collapse large inherited groups when they crowd the table.',
          'See a diagnostic when a type cannot be resolved.',
        ],
      },
      {
        title: 'Use it your way',
        items: [
          'Storybook 10 and 11 addons, plus a Vite plugin for build-time docs.',
          'CLI and Node binding for extraction, watch mode and custom tools; choose JSON, RDT or TOON output.',
          'An experimental TypeScript 7.1 CLI pass is an opt-in for the next alpha.',
        ],
      },
    ],
  },
  support: [
    {
      title: 'Outside Orin DX',
      content: {
        caption: 'External integrations',
        columns: ['integration', 'status'],
        rows: [
          ['Storybook 11', 'Addon for the docgen server; can fall back to Storybook’s own docgen'],
          ['Storybook 10', 'Vite plugin adds __docgenInfo; requires Vite 7 or 8'],
          ['Vite 7 and 8', 'Plugin exposes a JSON module and updates it over HMR'],
        ],
      },
    },
  ],
  typeBoundaries: {
    title: 'What those types look like',
    description:
      'First Caliper finds the component. Then it reads the shape of its props. These examples show where each step stands.',
    content: [
      {
        title: 'A typed React wrapper',
        code: `type Props = {\n  tone?: 'quiet' | 'loud'\n}\nexport const Button = memo(\n  (props: Props) => <button />\n)`,
        result: 'Found today. Caliper reads the named props and keeps the literal choices.',
        state: 'supported',
      },
      {
        title: 'Props reused from another type',
        code: `type Props = Pick<\n  ButtonProps,\n  'size' | 'disabled'\n>`,
        result:
          'Resolved today, including types from declaration files, imports and installed packages when dependency loading is on.',
        state: 'supported',
      },
      {
        title: 'A type that depends on a generic',
        code: `type Props<T> = T extends string\n  ? { label: T }\n  : { count: number }\nexport function Field(\n  props: Props<string>\n) {\n  return null\n}`,
        result:
          'The regular result can stay opaque. The experimental TypeScript 7.1 CLI opt-in in the next alpha can recover some props on exported function components.',
        state: 'experimental',
      },
      {
        title: 'A component Caliper cannot find yet',
        code: `const Button = styled.button\`\n  color: red;\n\``,
        result:
          'This styled template form may be missed. The checker reads components Caliper already found; it does not discover missing ones.',
        state: 'limited',
      },
    ],
  },
  worksWith: [{ tool: 'callisto', text: 'Callisto versions and publishes Caliper’s packages.' }],
  roadmap: {
    title: 'Coming up',
    description: 'The next alpha brings more of the current source work to npm.',
    content: [
      'Ship the on-demand Storybook 11 session, richer dependency support and experimental TypeScript 7.1 CLI pass.',
      'Keep closing prop gaps and speed up lazy sessions. Both have active PRs.',
      'Ask TypeScript only when Caliper is unsure about a component. That selective fallback is still planned.',
      'Rerun quality and speed comparisons once the open work lands. Early estimates put median speed near 31× RDT with dependencies loaded.',
    ],
  },
}

import type { ToolName } from '@pages/orin/ToolMark'

/**
 * How a number was come by, so a reader knows how much to trust it. A measured value was timed or counted on a run; a
 * derived one is worked out from measured values; a counted one is read off the tool's own support tables; a limit is a
 * ceiling the tool enforces.
 */
export type MetricKind = 'measured' | 'derived' | 'counted' | 'limit'

export interface MetricBar {
  label: string
  /** The value on the comparison's one scale. */
  value: number
  ours?: boolean
}

/** One number that matters, what it means in plain words and where it comes from. */
export interface MetricData {
  /** The tool the number is about, or the place the evidence is written up when it is about our own work. */
  tool?: ToolName
  link?: { label: string; href: string }
  value: string
  /** What the number means to someone choosing a tool. */
  meaning: string
  kind: MetricKind
  /** Exactly how it was measured or worked out: the machine, the corpus, the sum. */
  source: string
  /** Two or three bars drawn to scale, from zero, when the number is a comparison. */
  bars?: readonly MetricBar[]
}

// Every value below is one the tool's own page already states; the page for the tool is the first place to check it.
export const familyMetrics: readonly MetricData[] = [
  {
    tool: 'caliper',
    value: '28×',
    meaning: 'median speed against RDT on five libraries',
    kind: 'derived',
    source:
      'Median of 24×, 45×, 35×, 28× and 17×. Installed dependencies, 0.4.0 parity baseline, 2026-10-23. Current work has not been remeasured.',
  },
  {
    tool: 'lumen',
    value: '1.16 ms',
    meaning: 'to analyse 10,000 turns of an agent session',
    kind: 'measured',
    source: 'One analysis pass over synthetic turns with one file read each, 19 accumulators.',
  },
  {
    tool: 'monokl',
    value: '20,000',
    meaning: 'tokens, the most an answer can cost by default',
    kind: 'limit',
    source: 'A hard budget, with a 2 MB ceiling. Truncation is marked, never silent.',
  },
  {
    tool: 'callisto',
    value: '3',
    meaning: 'ecosystems released from one dependency graph',
    kind: 'counted',
    source: 'Cargo, npm and PyPI, each published with its own tools. Supported in 0.10.0.',
  },
]

/** Our own work, measured while building Orin DX: the figures the Principles page stands on. Small samples, and said so. */
export const evidenceMetrics: readonly MetricData[] = [
  {
    link: { label: 'principles', href: '/principles/#deterministic' },
    value: '8 of 8',
    meaning: 'specs stopped by a gate before any plan was written',
    kind: 'measured',
    source: 'Our gate verdicts for eight specs, 11 and 12 October 2026. 51 gate runs in all.',
  },
  {
    link: { label: 'principles', href: '/principles/#deterministic' },
    value: '5 of 13',
    meaning: 'plan commits had drifted from their spec when written',
    kind: 'measured',
    source: 'Four plans. The hash check exists to catch exactly this.',
  },
  {
    link: { label: 'principles', href: '/principles/#context' },
    value: '≤ 7%',
    meaning: 'of the plan and spec is what an agent actually read',
    kind: 'measured',
    source: 'Upper bound across 18 agents, with hand-compiled briefs, not a packet.',
  },
]

