---
import CaliperEvidence from '../../../layouts/CaliperEvidence.astro'
import { PageSection } from '@pages/orin/PageSection'
import { Table } from '@pages/orin/Table'
import { SourceNote } from '../../../components/source-note/sourceNote.tsx'
import { evidenceStack } from '../../../components/evidence-stack/evidenceStack.ts'
import { ParityPlot } from '../../../components/parity-plot/parityPlot.tsx'
import { MethodSteps } from '../../../components/method-steps/methodSteps.tsx'
import { css } from '@pages/orin/css'

// Accuracy is the weekly record of 2026-11-06 (main at c5fbb33e), from docs/rdt-differences.md. TypeScript 7.1's checker is the arbiter.
// `rdtWrong` is the share of the props RDT lists that the checker contradicts; `wrong` is Caliper's share of the props both report.
const accuracy = [
  { name: 'Mantine', shared: '20,104', agree: '90.9%', wrong: '0', rdtWrong: '0.04%' },
  { name: 'Chakra', shared: '486,832', agree: '100.0%', wrong: '0.0002%', rdtWrong: '0.006%' },
  { name: 'shadcn/ui', shared: '13,863', agree: '94.2%', wrong: '0.058%', rdtWrong: '0.59%' },
  { name: 'Ant Design', shared: '3,426', agree: '94.0%', wrong: '0', rdtWrong: '1.05%' },
  { name: 'React Spectrum', shared: '2,023', agree: '83.7%', wrong: '1.09%', rdtWrong: '5.02%' },
] as const
// Caliper 0.4.0 baseline, 2026-10-23, from docs/measurement.md. Newer extractor work has not been measured on this corpus yet.
const libraries = [
  { name: 'Mantine', components: '331 of 389', propsFoundPct: 99.7, sameControlPct: 93.1, type: '48.0%', cosmetic: '50.9%', caliper: '55 ms', rdt: '1.3 s' },
  { name: 'Chakra', components: '592 of 773', propsFoundPct: 98.6, sameControlPct: 100, type: '19.4%', cosmetic: '19.4%', caliper: '550 ms', rdt: '24.8 s' },
  { name: 'shadcn/ui', components: '1,519 of 1,594', propsFoundPct: 39.5, sameControlPct: 86.7, type: '61.3%', cosmetic: '74.7%', caliper: '115 ms', rdt: '4.0 s' },
  { name: 'Ant Design', components: '162 of 258', propsFoundPct: 80.3, sameControlPct: 94.8, type: '69.6%', cosmetic: '78.5%', caliper: '86 ms', rdt: '2.4 s' },
  { name: 'React Spectrum', components: '1,087 of 1,408', propsFoundPct: 99.7, sameControlPct: 96.9, type: '67.4%', cosmetic: '68.9%', caliper: '130 ms', rdt: '2.2 s' },
] as const
const source = {
  label: 'source',
  links: [
    { label: 'Where Caliper differs from RDT and the checker', href: 'https://github.com/orin-dx/caliper/blob/main/docs/rdt-differences.md' },
    { label: 'October recall run', href: 'https://github.com/orin-dx/caliper/blob/main/docs/measurement.md' },
  ],
}
const methodSources = {
  label: 'source',
  links: [
    { label: 'Weekly record harness', href: 'https://github.com/orin-dx/caliper/blob/main/scripts/weekly.py' },
    { label: 'Weekly workflow', href: 'https://github.com/orin-dx/caliper/blob/main/.github/workflows/weekly.yml' },
  ],
}
const method = [
  { label: 'pin', title: 'Fix the project', text: 'Each public repo is checked out at a named commit and installed with its own package manager. Its dependencies can resolve.' },
  { label: 'filter', title: 'Match the source', text: 'Tests, stories, demos and declaration files are removed. Both read the same source; Caliper loads dependencies, full HTML attributes and unexported components.' },
  { label: 'score', title: 'Use named denominators', text: 'Match components by file and name. Count RDT’s non-React props on those components; compare controls only where both tools report a prop.' },
] as const
const plotTitle = css({ textStyle: 'item', color: 'text' })
const note = css({ textStyle: 'small', color: 'text.muted' })
const prose = css({ display: 'grid', gap: 'gap.paragraph', textStyle: 'reading', color: 'text.body' })
const cards = css({ display: 'grid', gap: 'gap.items', '@/tablet': { gridTemplateColumns: 'repeat(2, minmax(0, 1fr))' } })
const card = css({ display: 'grid', alignContent: 'start', gap: 'gap.glyph', padding: 'inset.card', borderWidth: 'hairline', borderStyle: 'solid', borderColor: 'border', borderRadius: 'card', bg: 'surface' })
const cardLabel = css({ textStyle: 'label', color: 'text.muted' })
const cardValue = css({ textStyle: 'numeral', color: 'text.measure', fontVariantNumeric: 'tabular-nums' })
const cardText = css({ textStyle: 'body', color: 'text.body' })
const points = css({ display: 'grid', gap: 'gap.items', paddingInlineStart: '6', listStyle: 'disc', textStyle: 'body', color: 'text.body' })
const link = css({ color: 'text', textDecoration: 'underline', textUnderlineOffset: 'underlineOffset', _focusVisible: { outline: '2px solid {colors.focus}', outlineOffset: '1' } })
---

<CaliperEvidence title="How right are the types?" summary="The goal is correct types for Storybook and for agents, judged by TypeScript’s own checker. Agreement with react-docgen-typescript is information, not the target. Here is the five-library readout, including where we are wrong." topic="prop parity">
  <PageSection id="shape-heading" label="the readout" title="Judged by the checker" description="For every prop both tools report, TypeScript 7.1’s checker says whether the type is the same, spelled differently, less precise or wrong. The weekly record of November 6.">
    <Table caption="Caliper and RDT against TypeScript’s checker, weekly record of November 6, 2026 (main at c5fbb33e)" columns={['library', 'props compared', 'Caliper agrees', 'Caliper wrong', 'RDT wrong, of the props it lists']} rows={accuracy.map((library) => [library.name, library.shared, library.agree, library.wrong, library.rdtWrong])} />
    <SourceNote slot="aside" note={source} />
  </PageSection>

  <PageSection id="read-heading" label="the short read" title="What stands out" description="“Wrong” is the number that matters. “Agree” is the looser one: it counts only identical and differently spelled types.">
    <div class={cards}>
      <div class={card}><span class={cardLabel}>wrong, fewer than RDT</span><strong class={cardValue}>5 of 5</strong><p class={cardText}>libraries, as recorded. RDT’s wrong share runs 0.006% to 5.02%, Caliper’s 0 to 1.09%. RDT’s share is over the props it lists, so the denominators differ.</p></div>
      <div class={card}><span class={cardLabel}>our own comparison’s mistakes</span><strong class={cardValue}>28 of 31</strong><p class={cardText}>of the “wrong” verdicts above were index signatures our comparison read as fields. It was fixed after this run, so the next weekly record should show lower wrong rates. Treat these figures as an upper bound.</p></div>
    </div>
  </PageSection>

