import { CodeBlock } from '@pages/orin/CodeBlock'
import { sva } from '@pages/orin/css'
import type { TypeBoundary } from '../../data/toolPage.ts'

const typeBoundaries = sva({
  slots: ['list', 'item', 'heading', 'title', 'state', 'sample', 'result'],
  base: {
    list: { display: 'grid', listStyle: 'none' },
    item: {
      display: 'grid',
      gap: 'gap.items',
      paddingBlock: 'gap.paragraph',
      borderBlockStartWidth: 'hairline',
      borderBlockStartStyle: 'solid',
      borderColor: 'border',
    },
    heading: {
      display: 'flex',
      alignItems: 'baseline',
      justifyContent: 'space-between',
      flexWrap: 'wrap',
      gap: 'gap.glyph',
    },
    title: { textStyle: 'item', color: 'text' },
    state: { textStyle: 'label', color: 'text.muted' },
    sample: { minWidth: '[0]' },
    result: { textStyle: 'body', color: 'text.body' },
  },
})

const styles = typeBoundaries()
const stateLabel: Record<TypeBoundary['state'], string> = {
  supported: 'Works today',
  experimental: 'Next alpha · CLI opt-in',
  limited: 'Still working on it',
}

/** Concrete type shapes, with the result next to each example. */
export function TypeBoundaries({ items }: { items: readonly TypeBoundary[] }) {
  return (
    <ol className={styles.list}>
      {items.map((item) => (
        <li key={item.title} className={styles.item}>
          <div className={styles.heading}>
            <h3 className={styles.title}>{item.title}</h3>
            <span className={styles.state}>{stateLabel[item.state]}</span>
          </div>
          <div className={styles.sample}>
            <CodeBlock code={item.code} language="tsx" aria-label={`${item.title} example`} />
          </div>
          <p className={styles.result}>{item.result}</p>
        </li>
      ))}
    </ol>
  )
}

