import { mergeSlots, type SlotClasses } from '@pages/foundations/slots'
import type { ComponentPropsWithRef, ReactNode } from 'react'
import { pageIntro } from '../../styled-system/recipes'
import { Lattice } from '../lattice/lattice.tsx'

export type PageIntroProps = Omit<ComponentPropsWithRef<'header'>, 'children' | 'className'> & {
  label: string
  title: string
  lede: ReactNode
  width?: 'text' | 'page'
  /** Decorative art beside the heading, drawn over the lattice (a ribbon, on a page with no mark). */
  art?: ReactNode
  /** `p` for a specimen of the opener, so a page that shows it keeps one h1. */
  headingAs?: 'h1' | 'p'
  /** The title's id, so a region around the opener can be named by it. */
  headingId?: string
  classes?: SlotClasses<typeof pageIntro>
}

/** A page heading aligned to the Orin frame. */
export function PageIntro({
  label,
  title,
  lede,
  width = 'text',
  art,
  headingAs = 'h1',
  headingId,
  classes,
  ...props
}: PageIntroProps) {
  const slots = mergeSlots(pageIntro({ width, art: Boolean(art) }), classes)
  const Heading = headingAs
  return (
    <header
      {...props}
      data-recipe="page-intro"
      data-width={width}
      data-slot="root"
      className={width === 'page' ? `${slots.root} lx-band` : slots.root}
    >
      <span aria-hidden="true" data-slot="art" className={slots.art}>
        <Lattice soft level="page" />
        {art}
      </span>
      <span data-slot="label" className={`lx-label ${slots.label}`}>
        <span data-slot="brace" className={slots.brace}>
          {'{'}
        </span>{' '}
        {label}{' '}
        <span data-slot="brace" className={slots.brace}>
          {'}'}
        </span>
      </span>
      <Heading id={headingId} data-slot="title" className={slots.title}>
        {title}
      </Heading>
      <p data-slot="lede" className={slots.lede}>
        {lede}
      </p>
    </header>
  )
}
