// One anatomy for every page opener (the home hero, a tool page's hero, a page intro, the brand page's opener), so they
// are the same thing and sit in the same place: a brace kicker above the title in one size, the title in one role (balanced,
// two lines at most), the lede at one measure, then actions; and an art slot whose centre is ONE fixed point of the frame,
// the same on every page, with the lattice centred on it. Each recipe spreads these parts; none restates them.
//
// THE ONE VERTICAL ROLE: the nav's bottom to the first element of every opener (the breadcrumb row on a page that has one,
// otherwise the kicker) is `gap.block` (48) at every width. It is `first` below, defined once, and the art's centre derives from it
// (the first element's top plus half the largest art, so the home mark's top lines up with the kicker's top), so moving
// the role moves the text, the art and the lattice together.
//
// The fixed point: the right of two columns of the frame, or the right end of the reading column, whichever is further
// right (75% across the frame, or 86% across the reading column), and `first` plus half the large art below the nav. The
// reading column's start and width come from
// the frame tokens (the page's outer margin or its gutter, then the rail and the gap; at most the reading width, less
// what the window leaves), so the point stays proportional in the staged template (1024) and at both rails (1440). The
// art is positioned against the page's own frame (`main` is the positioned ancestor), and shows from the breakout width up;
// below it the art leads the opener in the flow and the lattice is centred on it there.
const gutter = '{spacing.page.gutter}'
const first = '{spacing.gap.block}'
// The home mark's optical offsets from the fixed point, named so they are one place: right by one `gap.items` step plus
// 32 (44), and up by 22. The lattice stays at the fixed point (the mark sits off its centre by these amounts).
const homeNudge = '{spacing.gap.items} + {spacing.8}'
const homeLift = '22px'
// A mark at the side of a phone's opener: a little over 100px, so it is clearly the page's mark and not a glyph.
const markSide = '[calc({spacing.24} + {spacing.4})]'
/**
 * Below the desktop frame an opener's art is out of the grid, so its first row is empty: no gap for it, and beside a mark the
 * title is narrowed to clear it (the opener's width less the mark and a step).
 */
export const openerMarkClear = {
  rowGap: '0',
  '&:has([data-recipe="brand-mark"]) [data-slot="title"], &:has([data-recipe="tool-mark"]) [data-slot="title"]': {
    maxWidth: '[calc(100% - {spacing.24} - {spacing.4} - {spacing.gap.items})]',
  },
} as const
// A tool page's mark: left by 22 and up by 42 of the fixed point (optical offsets, the owner's values). The lattice stays at the
// fixed point; the glow behind the mark follows the mark.
interface Nudge {
  left: string
  up: string
}
const noNudge: Nudge = { left: '0px', up: '0px' }
// The brand page's mark: left by 12 and up by 52 of the fixed point, and its lede measure one `gap.block` narrower so it wraps earlier.
export const brandNudge: Nudge = { left: '12px', up: '52px' }
export const toolNudge: Nudge = { left: '22px', up: '42px' }
// Every x below is in the page frame's (`main`'s) own width: `100%` where the art is positioned against `main`, `100vw`
// where an opener works out its text measure from the window (a container query unit would be the opener's own).
const xs = (w: '100%' | '100vw') => {
  const pageLeft = `max(${gutter}, (${w} - {sizes.page}) / 2)`
  const frameWidth = `min({sizes.page}, ${w} - 2 * ${gutter})`
  const columnStart = `${pageLeft} + {sizes.rail} + {sizes.gap}`
  const columnWidth = `min({sizes.reading}, ${w} - 2 * ${gutter} - {sizes.rail} - {sizes.gap})`
  // The fixed point: further right of 75% across the frame and 86% across the reading column.
  const point = `max(${pageLeft} + ${frameWidth} * 0.75, ${columnStart} + (${columnWidth}) * 0.86)`
  // The home art's centre: the fixed point nudged right by `homeNudge` (an optical balance offset), kept so the art's box
  // stays inside the frame.
  const home = `min(${point} + ${homeNudge}, ${pageLeft} + ${frameWidth} - {sizes.heroMark} / 2)`
  return { pageLeft, columnStart, point, home }
}
const onMain = xs('100%')
const onWindow = xs('100vw')
/** The page frame's x positions measured in window units, for what sits outside an opener (the footer echo's tile phase). */
export const windowX = onWindow

/**
 * The art slot at the fixed point; `size` is the size token of the art: the large hero size for the home page, the narrow one
 * for every other page. `lift` is what the page puts above its frame (a tool page's breadcrumb trail sits above `main`), so
 * the point is the same distance below the nav on every page.
 */
export const openerArt = (size: 'heroMark' | 'heroMarkNarrow', lift = '0px', nudge: Nudge = noNudge) => ({
  position: 'relative',
  display: 'block',
  width: '[100%]',
  maxWidth: size,
  aspectRatio: '1',
  gridColumn: '1',
  gridRow: '1',
  justifySelf: 'start',
  '& > img, & > svg': { display: 'block', width: '[100%]', height: 'auto' },
  // Below the desktop frame the art never leads the opener or takes the top of the screen. A ribbon with its lattice sits behind
  // the text, smaller and faded, out of the flow; a mark is a small one (96px) in the flow, with its lattice smaller too.
  _belowFrameDesktop: {
    '&:has([data-recipe="ribbon"])': {
      position: 'absolute',
      insetInlineStart: '0',
      insetBlockStart: '0',
      // The landing page's slot, on every page: the ribbon sits at the same place wherever it is used.
      width: 'heroMark',
      maxWidth: 'none',
      height: '[calc({spacing.24} * 3.5)]',
      aspectRatio: 'auto',
      opacity: '0.55',
      zIndex: '-1',
      pointerEvents: 'none',
    },
    // A mark is a block at the side, top right, level with the kicker; the title is narrowed to clear it (see `openerMarkClear`).
    '&:not(:has([data-recipe="ribbon"]))': {
      position: 'absolute',
      // Lifted by a step so it sits level with the kicker and the title, not hanging into the lede.
      insetBlockStart: `[calc(${first} - ${lift} - {spacing.6})]`,
      insetInlineEnd: `[max(${gutter}, (100% - {sizes.page}) / 2)]`,
      width: markSide,
      maxWidth: 'none',
    },
    '& > [data-recipe="lattice"], & > [data-recipe="lit-lattice"], & > [data-recipe="ribbon"]': { scale: '0.6' },
  },
  _frameDesktop: {
    position: 'absolute',
    width: size,
    insetInlineStart: `[calc(${onMain.point} - ${nudge.left})]`,
    insetBlockStart: `[calc(${first} + {sizes.heroMark} / 2 - ${lift} - ${nudge.up})]`,
    translate: '-50% -50%',
    '--lattice-dx': nudge.left,
    '--lattice-dy': nudge.up,
  },
})

/**
 * Custom properties an opener root sets: half the art's width, and how far the fixed point is from the opener's own left edge
 * (`reach`): 86% of the reading column for an opener that starts at the column (the brand page, a text intro), or that plus
 * the left rail and its gap for one that starts at the page's edge (home, a tool page, a page-wide intro).
 */
export const openerHalf = (size: 'heroMark' | 'heroMarkNarrow') => ({
  '--opener-art-half': `calc({sizes.${size}} / 2)`,
})
export const openerReach = {
  column: { '--opener-reach': `calc(${onWindow.point} - (${onWindow.columnStart}))` },
  page: { '--opener-reach': `calc(${onWindow.point} - (${onWindow.pageLeft}))` },
}

/** The text measure: it ends one block gap before the art's left edge (the fixed point less half the art). */
export const openerMeasure = {
  _frameDesktop: { maxWidth: '[calc(var(--opener-reach) - var(--opener-art-half) - {spacing.gap.block})]' },
}

/** The brand page's lede: one more `gap.block` off the measure than the shared one. */
export const openerLedeBrand = {
  _frameDesktop: { maxWidth: '[calc(var(--opener-reach) - var(--opener-art-half) - 2 * {spacing.gap.block})]' },
}

/** The opener's own top margin: the role that puts its first element below the nav (a page with a trail uses its own, below). */
export const openerFirst = { marginBlockStart: 'gap.block' } as const

export const openerKicker = { display: 'block', color: 'text.muted', textStyle: 'label' } as const
export const openerBrace = { color: 'text.accent' } as const
export const openerTitle = {
  margin: '0',
  marginBlockStart: 'gap.label',
  color: 'text',
  textStyle: 'title',
  textWrap: 'balance',
} as const
export const openerLede = {
  margin: '0',
  marginBlockStart: 'gap.heading',
  color: 'text.muted',
  textStyle: 'lede',
  ...openerMeasure,
} as const
export const openerActions = {
  display: 'flex',
  flexWrap: 'wrap',
  alignItems: 'center',
  gap: 'gap.normal',
  marginBlockStart: 'gap.paragraph',
} as const

/**
 * The optical start edge of an opener that starts at the page's edge (home, a tool page, a page-wide intro), under the nav's
 * logo: the logo's ink starts 4px inside its box, the kicker's brace, the lede's first letter and the button's edge start 0 to
 * 3px inside theirs. One step (the 4px role) on the kicker, lede and actions puts every ink edge within 1px of the logo's (the
 * title's own bearing is already within 1px). Not applied to an opener that starts at the reading column: it aligns
 * with the chapters under it.
 */
export const openerInk = { paddingInlineStart: '1' } as const
/** The title's own bearing is proportional to its size (about 2.5% of it past the logo's ink), so its optical offset is too. */
export const openerTitleInk = { paddingInlineStart: '[0.025em]' } as const

// ---- the home page's art ---------------------------------------------------------------------------------------------------
// Home's mark is the fixed point too, only kept inside the frame: where the fixed point would put the mark's box past the
// frame's right edge (a narrow window), the mark's box ends at the frame's edge instead, and the lattice (always at the fixed
// point) is offset from it by `--lattice-dx`. The lit mark's ink is 0.79 of its slot (a bearing of about 0.108 of the slot each
// side, measured by pixels at 1440 in both themes), which the text measure uses to end before the ink, not the box.
const bearing = 'calc({sizes.heroMark} * 0.108)'
const inkHalf = `({sizes.heroMark} / 2 - ${bearing})`

export const openerArtHome = {
  _frameDesktop: {
    insetInlineStart: `[calc(${onMain.home})]`,
    insetBlockStart: `[calc(${first} + {sizes.heroMark} / 2 - ${homeLift})]`,
    '--lattice-dx': `calc(${onWindow.point} - (${onWindow.home}))`,
    '--lattice-dy': homeLift,
  },
}

/** The home measure: custom properties so the title and lede end one block gap before the mark's left ink edge. */
export const openerReachHome = {
  '--opener-art-half': `calc${inkHalf}`,
  '--opener-reach': `calc(${onWindow.home} - (${onWindow.pageLeft}))`,
}

/** The home lede: at most the lede measure (about 75 characters a line at its size), and never past the mark. */
export const openerLedeCapped = {
  _frameDesktop: {
    maxWidth: '[min({sizes.lede}, calc(var(--opener-reach) - var(--opener-art-half) - {spacing.gap.block}))]',
  },
}

