import { defineSlotRecipe } from '@pandacss/dev'
import {
  openerArt,
  openerBrace,
  openerKicker,
  openerLede,
  openerFirst,
  openerHalf,
  openerInk,
  openerTitleInk,
  openerMeasure,
  openerReach,
  openerTitle,
} from '../opener/openerAnatomy.ts'

// A page intro (the tools index, principles, any page without art): the shared opener anatomy, with an EMPTY art slot at
// the same fixed point as every other opener's art, so the lattice is centred in the same place on every page. Like
// PageSection, a page-width intro is a frame band: its parts keep to the measure on the band's left edge.
export const pageIntroRecipe = defineSlotRecipe({
  className: 'orin-page-intro',
  slots: ['root', 'art', 'label', 'brace', 'title', 'lede'],
  base: {
    root: { ...openerFirst, paddingBlockEnd: '0', ...openerHalf('heroMarkNarrow'), ...openerReach.column },
    art: {
      ...openerArt('heroMarkNarrow'),
      pointerEvents: 'none',
      _frameDesktop: { ...openerArt('heroMarkNarrow')._frameDesktop, height: 'heroMarkNarrow' },
    },
    label: openerKicker,
    brace: openerBrace,
    title: { ...openerTitle, ...openerMeasure },
    lede: openerLede,
  },
  variants: {
    width: {
      text: {},
      page: { root: openerReach.page, label: openerInk, title: openerTitleInk, lede: openerInk },
    },
    // An opener with art beside it keeps its text in a column that ends where the strands begin, packed at the top.
    art: {
      true: {
        root: { alignContent: 'start' },
        title: { maxWidth: 'reading' },
        lede: { maxWidth: 'lede' },
      },
    },
  },
  defaultVariants: { width: 'text' },
})

