import { mergeSlots, type SlotClasses } from '@pages/foundations/slots'
import type { ComponentPropsWithRef, CSSProperties } from 'react'
import { litLattice, type LitLatticeVariant } from '../../styled-system/recipes'
import { fieldBox, ribbonGeometry, type RibbonPath } from '../ribbon/ribbonPresets.ts'

export type LitLatticeProps = Omit<ComponentPropsWithRef<'div'>, 'children' | 'className'> &
  LitLatticeVariant & { path?: RibbonPath; classes?: SlotClasses<typeof litLattice> }

type CustomProperties = Record<`--${string}`, string>

/** The ribbon's outline as a blurred mask image, in the lattice field's own units. */
function silhouette(path: RibbonPath): string {
  const { spine } = ribbonGeometry(path)
  const line = spine.map((p) => `${p.x} ${p.y}`).join(' L ')
  const svg =
    `<svg xmlns='http://www.w3.org/2000/svg' width='${fieldBox.width}' height='${fieldBox.height}'>` +
    `<defs><filter id='b' x='-30%' y='-30%' width='160%' height='160%'><feGaussianBlur stdDeviation='16'/></filter></defs>` +
    `<g filter='url(#b)'><path d='M ${line}' fill='none' stroke='white' stroke-width='96' stroke-linecap='round' stroke-linejoin='round'/></g></svg>`
  return `url("data:image/svg+xml;utf8,${encodeURIComponent(svg)}")`
}

/** Decorative: lights the lattice cells under a ribbon. A sibling of the Lattice, in the same art slot. */
export function LitLattice({ tone, path = 'hero', classes, style, ...props }: LitLatticeProps) {
  const slots = mergeSlots(litLattice({ tone }), classes)
  const vars: CSSProperties & CustomProperties = { ...style, '--lit-silhouette': silhouette(path) }
  return (
    <div
      {...props}
      aria-hidden="true"
      data-recipe="lit-lattice"
      data-tone={tone ?? 'ramp'}
      data-path={path}
      data-slot="root"
      className={slots.root}
      style={vars}
    />
  )
}
import { defineSlotRecipe } from '@pandacss/dev'
import { fieldHeight, fieldWidth, hexMask } from '../lattice/latticeRecipe.ts'

type Family = 'know' | 'build' | 'measure' | 'ship'
const family = (id: Family) => ({ root: { bg: `{colors.family.${id}}` } })

// The lattice cells under a ribbon, lit. It reuses the lattice's own hexagon mask and cell size and the same box and
// placement, so every lit cell is a real cell. `--lit-silhouette` (set by the component) is the ribbon's blurred outline.
const silhouetteAndCells = `var(--lit-silhouette), ${hexMask}`
const sizes = '100% 100%, {sizes.lattice.cellWidth} {sizes.lattice.cellHeight}'

export const litLatticeRecipe = defineSlotRecipe({
  className: 'orin-lit-lattice',
  slots: ['root'],
  base: {
    root: {
      position: 'absolute',
      insetInlineStart: '[calc(50% + var(--lattice-dx, 0px))]',
      insetBlockStart: '[calc(50% + var(--lattice-dy, 0px))]',
      width: `[${fieldWidth}]`,
      height: `[${fieldHeight}]`,
      translate: '-50% -50%',
      zIndex: '-1',
      pointerEvents: 'none',
      opacity: '0.6',
      _dark: { opacity: '0.85' },
      maskImage: silhouetteAndCells,
      maskSize: sizes,
      maskRepeat: 'no-repeat, repeat',
      maskComposite: 'intersect',
      WebkitMaskImage: silhouetteAndCells,
      WebkitMaskSize: sizes,
      WebkitMaskRepeat: 'no-repeat, repeat',
      WebkitMaskComposite: 'source-in',
    },
  },
  variants: {
    tone: {
      ramp: {
        root: {
          bg: 'linear-gradient(90deg, {colors.ramp.1}, {colors.ramp.2} 35%, {colors.ramp.4} 70%, {colors.ramp.5})',
        },
      },
      know: family('know'),
      build: family('build'),
      measure: family('measure'),
      ship: family('ship'),
    },
  },
  defaultVariants: { tone: 'ramp' },
})
