import { mergeSlots, type SlotClasses } from '@pages/foundations/slots'
import { useId, type ComponentPropsWithRef } from 'react'
import { ribbon, type RibbonVariant } from '../../styled-system/recipes'
import { fieldBox, ribbonGeometry, type RibbonPath } from './ribbonPresets.ts'

export type RibbonProps = Omit<ComponentPropsWithRef<'svg'>, 'children' | 'className'> & {
  /** `ramp` for an Orin-wide page, a family for one tool's page. */
  tone?: NonNullable<RibbonVariant['tone']>
  path?: RibbonPath
  classes?: SlotClasses<typeof ribbon>
}

const bitSlots = ['bitA', 'bitB', 'bitC', 'bitD'] as const

/** The twisting bundle: wild at one end, pinched through gates, calmer at the other. Static SVG, drawn on the server. */
export function Ribbon({ tone = 'ramp', path = 'hero', classes, ...props }: RibbonProps) {
  const id = useId()
  const slots = mergeSlots(ribbon({ tone }), classes)
  const geometry = ribbonGeometry(path)
  const [first] = geometry.spine
  const last = geometry.spine.at(-1)
  const gradient = `${id}-g`
  const blur = `${id}-b`
  return (
    <svg
      viewBox={`0 0 ${fieldBox.width} ${fieldBox.height}`}
      {...props}
      aria-hidden="true"
      focusable="false"
      data-recipe="ribbon"
      data-tone={tone}
      data-path={path}
      data-slot="root"
      className={slots.root}
    >
      <defs>
        <linearGradient id={gradient} gradientUnits="userSpaceOnUse" x1={first?.x ?? 0} y1="0" x2={last?.x ?? 0} y2="0">
          {(['stop1', 'stop2', 'stop3', 'stop4'] as const).map((slot, i) => (
            <stop key={slot} offset={i / 3} className={slots[slot]} />
          ))}
        </linearGradient>
        <filter id={blur} x="-20%" y="-20%" width="140%" height="140%">
          <feGaussianBlur stdDeviation="5" />
        </filter>
      </defs>
      <g data-slot="glow" className={slots.glow} filter={`url(#${blur})`}>
        {geometry.strands.map((s, i) =>
          s.glow ? (
            <path key={i} d={s.d} stroke={`url(#${gradient})`} strokeWidth="5" opacity="0.5" className={slots.strand} />
          ) : null,
