import { renderToStaticMarkup } from 'react-dom/server'
import { expect, test } from 'vitest'
import { Hero } from '../hero/hero.tsx'
import { PageIntro } from '../page-intro/pageIntro.tsx'
import { ToolHero } from '../tool-hero/toolHero.tsx'

// The lattice is the aura of the art: it is a child of the art slot, so it is centred on the art by construction.
const insideArt = /data-slot="(mark|art)"[^>]*>(?:<[^>]*>)*?<div[^>]*data-recipe="lattice"/

test('a hero keeps its lattice in its mark slot', () => {
  expect(renderToStaticMarkup(<Hero label="x" title="t" lede="l" mark={<span />} />)).toMatch(insideArt)
})

test('a tool hero keeps its lattice in its mark slot', () => {
  const html = renderToStaticMarkup(
    <ToolHero tool="lumen" name="lumen" family="measure" description="d" stage={<span />} />,
  )
  expect(html).toMatch(insideArt)
})

const toolHero = (art?: 'mark' | 'strands' | 'none') =>
  renderToStaticMarkup(
    <ToolHero tool="lumen" name="lumen" family="measure" description="d" stage={<span />} art={art} />,
  )

test('a tool hero shows the lattice in every art mode, and the tool mark only in mark mode', () => {
  for (const art of ['mark', 'strands', 'none'] as const) expect(toolHero(art)).toMatch(insideArt)
  expect(toolHero('mark')).toContain('data-recipe="tool-mark"')
  expect(toolHero()).toContain('data-recipe="tool-mark"')
  expect(toolHero('strands')).not.toContain('data-recipe="tool-mark"')
  expect(toolHero('none')).not.toContain('data-recipe="tool-mark"')
})

test('a tool hero draws strands only in strands mode', () => {
  expect(toolHero('strands')).toContain('data-recipe="ribbon"')
  expect(toolHero('strands')).toContain('data-recipe="lit-lattice"')
  expect(toolHero('mark')).not.toContain('data-recipe="ribbon"')
  expect(toolHero('none')).not.toContain('data-recipe="ribbon"')
})

test('a tool hero keeps the family haze for the mark alone', () => {
  const haze = (art: 'mark' | 'strands' | 'none') => /orin-lattice--level_(\w+)/.exec(toolHero(art))?.[1]
  expect(haze('mark')).toBe('tool')
  expect(haze('strands')).toBe('toolField')
  expect(haze('none')).toBe('toolField')
})

test('a page intro with no art keeps its lattice in an empty art slot', () => {
  expect(renderToStaticMarkup(<PageIntro label="x" title="t" lede="l" />)).toMatch(insideArt)
})

