import { cva, sva } from '@pages/orin/css'

interface ComparisonValue {
  label: string
  text: string
  value: number
  role: 'focus' | 'reference'
}

interface ComparisonGroup {
  title: string
  change: string
  values: readonly ComparisonValue[]
}

interface ComparisonBarsProps {
  label: string
  groups: readonly ComparisonGroup[]
  method: string
}

const comparison = sva({
  slots: ['root', 'groups', 'group', 'head', 'title', 'change', 'row', 'label', 'track', 'value', 'method'],
  base: {
    root: {
      display: 'grid',
      gap: 'gap.paragraph',
      padding: 'inset.card',
      borderWidth: 'hairline',
      borderStyle: 'solid',
      borderColor: 'border',
      borderRadius: 'card',
      bg: 'surface',
    },
    groups: { display: 'grid', gap: 'gap.paragraph' },
    group: { display: 'grid', gap: 'gap.items' },
    head: {
      display: 'flex',
      flexWrap: 'wrap',
      alignItems: 'baseline',
      justifyContent: 'space-between',
      gap: 'gap.glyph',
    },
    title: { textStyle: 'item', color: 'text' },
    change: { textStyle: 'label', color: 'text.measure' },
    row: {
      display: 'grid',
      alignItems: 'center',
      gap: 'gap.glyph',
      gridTemplateColumns: '{spacing.12} minmax(0, 1fr) {spacing.16}',
      '@/tablet': { gridTemplateColumns: '{spacing.16} minmax(0, 1fr) {spacing.16}' },
    },
    label: { textStyle: 'small', color: 'text.muted' },
    track: {
      display: 'block',
      height: '[{spacing.3}]',
      borderRadius: 'pill',
      bg: 'surface.raised',
      overflow: 'hidden',
    },
    value: {
      textStyle: 'code',
      color: 'text',
      textAlign: 'right',
      whiteSpace: 'nowrap',
      fontVariantNumeric: 'tabular-nums',
    },
    method: { textStyle: 'small', color: 'text.muted' },
  },
})

const fill = cva({
  base: { display: 'block', height: 'fill', borderRadius: 'pill' },
  variants: {
    role: {
      focus: { bg: 'text.measure' },
      reference: { bg: 'text.muted' },
    },
  },
})

const styles = comparison()

/** Groups related timings in one figure, with each group's bars scaled to its own maximum. */
export function ComparisonBars({ label, groups, method }: ComparisonBarsProps) {
  return (
    <figure className={styles.root} aria-label={label}>
      <div className={styles.groups}>
        {groups.map((group) => {
          const max = Math.max(...group.values.map((item) => item.value))
          return (
            <div key={group.title} className={styles.group}>
              <div className={styles.head}>
                <h3 className={styles.title}>{group.title}</h3>
                <span className={styles.change}>{group.change}</span>
              </div>
              {group.values.map((item) => (
                <div key={item.label} className={styles.row}>
                  <span className={styles.label}>{item.label}</span>
                  <span className={styles.track} aria-hidden="true">
                    <span className={fill({ role: item.role })} style={{ width: `${(item.value / max) * 100}%` }} />
                  </span>
                  <span className={styles.value}>{item.text}</span>
                </div>
              ))}
            </div>
          )
        })}
      </div>
      <p className={styles.method}>{method}</p>
    </figure>
  )
}

