/* oxlint-disable jsx-a11y/no-noninteractive-tabindex, jsx-a11y/prefer-tag-over-role -- The root scrolls sideways when the table is wider than its column, so it is a named, keyboard-focusable scroll region. */
import { mergeSlots, type SlotClasses } from '@pages/foundations/slots'
import type { ComponentPropsWithRef, ReactNode } from 'react'
import { table } from '../../styled-system/recipes'

export type TableProps = Omit<ComponentPropsWithRef<'div'>, 'children' | 'className'> & {
  caption: string
  /** Keep the caption for assistive technology but do not draw it, when a heading above names the table. */
  hideCaption?: boolean
  columns: readonly string[]
  rows: readonly (readonly ReactNode[])[]
  classes?: SlotClasses<typeof table>
}

/** A captioned reference table. The first cell of each row is its row header. Its scroll area is named by the caption and reachable by keyboard. */
export function Table({ caption, hideCaption = false, columns, rows, classes, ...props }: TableProps) {
  const slots = mergeSlots(table({ captionHidden: hideCaption }), classes)
  return (
    <div
      role="region"
      aria-label={caption}
      tabIndex={0}
      {...props}
      data-recipe="table"
      data-slot="root"
      className={slots.root}
    >
      <table data-slot="table" className={slots.table}>
        <caption data-slot="caption" className={slots.caption}>
          {caption}
        </caption>
        <thead>
          <tr>
            {columns.map((column) => (
              <th key={column} scope="col" data-slot="head" className={slots.head}>
                {column}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, index) => (
            <tr key={index}>
              {row.map((cell, column) =>
                column === 0 ? (
                  <th key={column} scope="row" data-slot="cell" className={slots.cell}>
                    {cell}
                  </th>
                ) : (
                  <td key={column} data-slot="cell" className={slots.cell}>
                    {cell}
                  </td>
                ),
              )}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
