import CaliperEvidence from '../../../layouts/CaliperEvidence.astro'
import { PageSection } from '@pages/orin/PageSection'
import { Table } from '@pages/orin/Table'
import { RaceBars } from '../../../components/race-bars/raceBars.tsx'
import { ComparisonBars } from '../../../components/comparison-bars/comparisonBars.tsx'
import { MethodSteps } from '../../../components/method-steps/methodSteps.tsx'
import { SourceNote } from '../../../components/source-note/sourceNote.tsx'
import { evidenceStack } from '../../../components/evidence-stack/evidenceStack.ts'
import { css } from '@pages/orin/css'

const sources = {
  label: 'source',
  links: [
    { label: 'Weekly record harness', href: 'https://github.com/orin-dx/caliper/blob/main/scripts/weekly.py' },
    { label: 'Recorded runs', href: 'https://github.com/orin-dx/caliper/blob/main/docs/measurement.md' },
    { label: 'Storybook harness', href: 'https://github.com/orin-dx/caliper/blob/main/packages/storybook/scripts/storybook-parity.mjs' },
  ],
}
const protocol = [
  { label: 'inputs', title: 'Pin real projects', text: 'Five public repos at fixed commits, installed with their own package managers. Tests, stories, demos and declaration files are left out.' },
  { label: 'work', title: 'Read the same source', text: 'RDT parses the filtered TSX files as one program. Caliper reads the same source with dependencies, full HTML attributes and unexported components on.' },
  { label: 'clocks', title: 'Show the boundary', text: 'Five cold runs, seven installed-library runs and three interleaved before/after addon runs. Each result below says what its timer includes.' },
] as const
const race = {
  title: 'One cold Node harness, one set of 21 fixtures',
  method: 'Apple M5 Max, five runs, October 2026. About 0.32 s of every result is shared harness startup.',
  bars: [
    { label: 'Caliper', text: '0.38 s', value: 0.38, ours: true },
    { label: 'react-docgen', text: '0.52 s', value: 0.52 },
    { label: 'RDT', text: '4.9 s', value: 4.9 },
  ],
} as const
const requestComparison = {
  label: 'Storybook addon request time before and after the October 24 source changes',
  groups: [
    { title: 'All 129 requests', change: '71% less time', values: [
      { label: 'before', text: '2.17 s', value: 2.17, role: 'reference' },
      { label: 'after', text: '0.63 s', value: 0.63, role: 'focus' },
    ] },
    { title: 'Median per story', change: '73% less time', values: [
      { label: 'before', text: '15 ms', value: 15, role: 'reference' },
      { label: 'after', text: '4 ms', value: 4, role: 'focus' },
    ] },
  ],
  method: 'First request: 200 ms before, 150 ms after. Source builds interleaved, best of three.',
} as const
const runIndex = css({ display: 'grid', borderBlockStartWidth: 'hairline', borderBlockEndWidth: 'hairline', borderStyle: 'solid', borderColor: 'border', '@/tablet': { gridTemplateColumns: 'repeat(3, minmax(0, 1fr))' } })
const runLink = css({ display: 'grid', alignContent: 'start', gap: 'gap.glyph', padding: 'gap.items', borderBlockEndWidth: 'hairline', borderBlockEndStyle: 'solid', borderColor: 'border', color: 'text', textDecoration: 'none', transitionProperty: 'background', transitionDuration: 'stateOut', '&:last-child': { borderColor: 'transparent' }, '@/tablet': { borderBlockEndStyle: 'none', borderInlineEndWidth: 'hairline', borderInlineEndStyle: 'solid' }, _hover: { bg: 'surface.raised', transitionDuration: 'stateIn' }, _focusVisible: { outline: '2px solid {colors.focus}', outlineOffset: '1' }, _motionReduce: { transitionDuration: 'instant' } })
const label = css({ textStyle: 'label', color: 'text.muted' })
const number = css({ textStyle: 'numeral', color: 'text.measure', fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap' })
const cardTitle = css({ textStyle: 'item', color: 'text' })
const cardText = css({ textStyle: 'body', color: 'text.body' })
const jumpCue = css({ alignSelf: 'end', paddingBlockStart: 'gap.items', textStyle: 'small', color: 'text', textDecoration: 'underline', textUnderlineOffset: 'underlineOffset' })
const small = css({ textStyle: 'small', color: 'text.muted' })
const prose = css({ display: 'grid', gap: 'gap.paragraph', textStyle: 'reading', color: 'text.body' })
const points = css({ display: 'grid', gap: 'gap.items', paddingInlineStart: '6', listStyle: 'disc', textStyle: 'body', color: 'text.body' })
const flow = css({ display: 'grid', gap: 'gap.items', '@/tablet': { gridTemplateColumns: 'repeat(4, minmax(0, 1fr))' } })
const step = css({ display: 'grid', alignContent: 'start', gap: 'gap.glyph', paddingBlockStart: 'gap.items', borderBlockStartWidth: 'hairline', borderBlockStartStyle: 'solid', borderColor: 'border' })
const stepNum = css({ color: 'text.muted', textStyle: 'label' })
const pair = css({ display: 'grid', gap: 'gap.items', '@/tablet': { gridTemplateColumns: 'repeat(2, minmax(0, 1fr))' } })
const experiment = css({ display: 'grid', alignContent: 'start', gap: 'gap.glyph', paddingBlockStart: 'gap.items', borderBlockStartWidth: 'hairline', borderBlockStartStyle: 'solid', borderColor: 'border' })
