// Caliper's weekly record of 2026-11-09 (weekly.json, run 42637254796), Caliper 0.10.0, on a shared CI runner. The parity and
// measurement pages read their figures from here, so one dated snapshot feeds both and they cannot drift apart.
//
// Verdict figures are oracle.tools.* over the props each tool lists, judged by TypeScript 7.1's checker. Components are RDT's
// entries with props, less non-components and repeats. Time and memory are one whole process each, Node start included: the
// median of five runs for Caliper, one run for RDT.
export const record = {
  date: '2026-11-09',
  dateLabel: 'November 9, 2026',
  caliper: '0.10.0',
} as const

export interface LibraryRecord {
  name: string
  wrongC: number
  wrongR: number
  /** Props each tool lists in the checker's universe. */
  nC: number
  nR: number
  /** The share of listed props that match the checker. */
  listC: number
  listR: number
  verdict: 'better' | 'close' | 'behind'
  lessC: number
  lessR: number
  /** The share of real components Caliper reports, and the count it is of. */
  comps: number
  compsOf: string
  msC: number
  msR: number
  mibC: number
  mibR: number
}

export const libraries: readonly LibraryRecord[] = [
  { name: 'Mantine', wrongC: 0, wrongR: 9, nC: 20_104, nR: 20_117, listC: 93.6, listR: 97.1, verdict: 'behind', lessC: 1281, lessR: 576, comps: 89.1, compsOf: '328 of 368', msC: 286, msR: 4694, mibC: 219, mibR: 539 },
  { name: 'Chakra', wrongC: 1, wrongR: 30, nC: 486_832, nR: 521_632, listC: 100, listR: 96.8, verdict: 'better', lessC: 19, lessR: 16_642, comps: 92.5, compsOf: '614 of 664', msC: 903, msR: 59_268, mibC: 451, mibR: 2084 },
  { name: 'shadcn/ui', wrongC: 0, wrongR: 76, nC: 13_863, nR: 13_896, listC: 94.5, listR: 88.1, verdict: 'better', lessC: 696, lessR: 1519, comps: 97.1, compsOf: '1,527 of 1,573', msC: 629, msR: 10_206, mibC: 353, mibR: 1400 },
  { name: 'Ant Design', wrongC: 1, wrongR: 36, nC: 3426, nR: 3442, listC: 94.2, listR: 93.8, verdict: 'close', lessC: 195, lessR: 178, comps: 93.1, compsOf: '188 of 202', msC: 156, msR: 6069, mibC: 179, mibR: 1038 },
  { name: 'React Spectrum', wrongC: 0, wrongR: 138, nC: 2023, nR: 2747, listC: 84.7, listR: 86.3, verdict: 'close', lessC: 102, lessR: 52, comps: 97.6, compsOf: '998 of 1,023', msC: 274, msR: 5994, mibC: 233, mibR: 816 },
]

/** How many times RDT's figure is Caliper's, for time and for memory. */
export const speedRatio = (library: LibraryRecord) => library.msR / library.msC
export const memoryRatio = (library: LibraryRecord) => library.mibR / library.mibC

const median = (values: readonly number[]) => [...values].sort((a, b) => a - b)[Math.floor(values.length / 2)] as number
export const medianSpeed = median(libraries.map(speedRatio))
export const medianMemory = median(libraries.map(memoryRatio))

