---
// A long document: the chapter rail and the page's chapters, in the structure SPEC-003a requires (the rail root is
// the preceding sibling of <main>, in a wrapper holding nothing else). Every document page is built on this, so none
// can lose its rail or place it wrongly. It is also a reading page: below the rail width, labels take the left rail and
// content the centre. A `lead` (a hero that runs the page's width, over the rails) renders before the wrapper, so the rail and
// the chapters start under it, as on a case study. The lead is a region named by its h1 (`leadHeadingId`), as a case
// study's and a post's headers are, so its words sit in a landmark and an opener's own <header> is not a second banner.
// The footer slot renders after the wrapper.
import ChapterNav from '../chapter-nav/chapterNav.astro'
import type { Chapter } from '../chapter-nav/chapterTypes.ts'

interface Props {
  chapters: readonly Chapter[]
  /** The accessible name of the chapter list. */
  label?: string
  /** The id of the lead's h1, which names the lead's region. Required with a lead. */
  leadHeadingId?: string
}
const { chapters, label, leadHeadingId } = Astro.props
const hasLead = Astro.slots.has('lead')
if (hasLead && !leadHeadingId) throw new Error('DocumentPage: a lead needs leadHeadingId, the id of its h1, to name its region.')
---

{
  hasLead && (
    <section data-document-lead aria-labelledby={leadHeadingId}>
      <slot name="lead" />
    </section>
  )
}
<div data-document-page data-has-lead={hasLead ? '' : undefined}>
  <ChapterNav chapters={chapters} label={label} />
  <main id="main" data-reading><slot /></main>
</div>
<slot name="footer" />
