---
import Base from '../layouts/Base.astro'
import { PrinciplesHero } from '../components/principles-hero/principlesHero.tsx'
import DocumentPage from '@pages/components/frame/documentPage.astro'
import { PageSection } from '@pages/orin/PageSection'
import { Button } from '@pages/orin/Button'
import { Ledger } from '@pages/orin/Ledger'
import { Claim } from '../components/principle-claim/principleClaim.tsx'
import { IndustryItem, IndustryList } from '../components/industry-list/industryList.tsx'
import { Actions, Cite, Code, Lead, List, Part, ProseBody, Reason, Reasons, Tile, Tiles } from '../components/principle-prose/principleProse.tsx'
import { repositories, sources } from '../components/principle-sources/principleSources.ts'
import { toolHref, tools, type ToolFamily } from '../data/tools.ts'

// The page is a position, not a report of results, in the voice of brand/design-system/project/voice.md: short
// sentences, one idea each. Each principle runs in one order: the position and the commitment, then what it is, why,
// how, where the industry is heading, what we have seen so far and how we will prove it. Every figure is in
// docs/proposals/orin-principles-evidence.md; every industry source is in docs/proposals/orin-principles-direction.md,
// and its link is in principleSources.ts.
const families: readonly { id: ToolFamily; name: string; description: string }[] = [
  { id: 'know', name: 'Know', description: 'Find code and keep project knowledge on disk.' },
  { id: 'build', name: 'Build', description: 'Shape what agents read and generate what they shouldn’t write by hand.' },
  { id: 'measure', name: 'Measure', description: 'See what sessions cost, test changes, watch code health.' },
  { id: 'ship', name: 'Ship', description: 'Version and publish releases across ecosystems.' },
]
const named = (name: string) => name.charAt(0).toUpperCase() + name.slice(1)
// The chapter rail numbers the sections, so each section's label is a word, not a second number.
const chapters = [
  { id: 'deterministic', label: 'out of the loop' },
  { id: 'context', label: 'compiled context' },
  { id: 'improve', label: 'measure and improve' },
  { id: 'tools', label: 'what you get' },
  { id: 'audience', label: 'who it is for' },
  { id: 'start', label: 'where to start' },
] as const
---

<Base title="Principles · Orin DX" description="How Orin DX tools work with coding agents, and what you can expect from each." current="principles">
  <DocumentPage chapters={chapters} leadHeadingId="principles-title">
    <Fragment slot="lead">
      <div class="lx-frame">
        <PrinciplesHero headingId="principles-title" />
        <ProseBody>
          <Part>
            <p>Agent work outlives a context window, and criteria drop out as it compresses.</p>
            <p>Our position and where we are taking it. Evidence as we get it.</p>
          </Part>
        </ProseBody>
      </div>
    </Fragment>

    <PageSection id="deterministic" label="out of the loop" title="Deterministic work, out of the loop" content="text" width="frame">
      <ProseBody>
        <Claim
          position="If a program can do it, the agent shouldn’t."
          commitment="If a program can check it, a program checks it; output that fails its schema stops the run. Limit: the Wisp CLI is unpublished, so agents run some checks today."
        />

        <Part title="What" stop={1}>
          <p>A program does the work that needs no judgment. The agent keeps the rest.</p>
          <p>Example: a script hashes the spec and compares it with the hash the plan recorded.</p>
// ChapterNav's props (SPEC-003a api_surface). Chapters are props only: the component never reads the page's headings.

export interface ChapterChild {
  id: string
  label: string
}

export interface Chapter {
  id: string
  label: string
  /** The part this chapter belongs to: a short label (1 to 3 words) shown above its first chapter in the list. */
  group?: string
  children?: readonly ChapterChild[]
}

export interface ChapterNavProps {
  /** The chapters in page order: 0 throws, 1 to 3 render nothing, 4 to 24 render. Either every chapter has a `group` or none does. */
  chapters: readonly Chapter[]
  /** The accessible name of the Chapters navigation (1 to 24 characters). */
  label?: string
  /** The Back to top link's text (1 to 40 characters). */
  topLabel?: string
}

/**
 * What a caller may pass at runtime, wider than the typed props so validation can name the mistake: a child that
 * carries its own children, or a value that is not a string.
 */
export interface ChildInput {
  id: string
  label: string
  children?: readonly ChildInput[]
}

export interface ChapterInput {
  id: string
  label: string
  group?: string
  children?: readonly ChildInput[]
}

/** The props after validation, with defaults applied; `show` is false for 1 to 3 chapters. */
export interface ResolvedChapterNav {
  chapters: readonly Chapter[]
  label: string
  topLabel: string
  show: boolean
}
