import { mergeSlots, type SlotClasses } from '@pages/foundations/slots'
import type { ComponentPropsWithRef, ReactNode } from 'react'
import { pageSection } from '../../styled-system/recipes'
import { SectionLabel } from '../section-label/sectionLabel.tsx'

export type PageSectionProps = Omit<ComponentPropsWithRef<'section'>, 'children' | 'className'> & {
  id: string
  /** The { scope } label; leave it out when the heading already says it (a family name under its family). */
  label?: string
  title: string
  description?: ReactNode
  children?: ReactNode
  /** Under the description, on the text column: a short key or list. */
  summary?: ReactNode
  /** Level with the content in the right rail on reading pages (facts, a note); after it elsewhere. */
  aside?: ReactNode
  /**
   * band: a page-width subgrid; the label takes the left rail on reading pages, the heading and text the centre.
   * text: one block on the text column, at the measure. frame: its own frame, for documents whose chapters place
   * notes and wide pieces themselves (pass them as direct children).
   */
  width?: 'band' | 'text' | 'frame'
  /** What the content is: wide (collections, samples, tables) or text (reading at the measure). Bands only. */
  content?: 'wide' | 'text'
  last?: boolean
  classes?: SlotClasses<typeof pageSection>
}

/** A section with Orin's standard vertical and type rhythm, placed on the page grid by its width. */
export function PageSection({
  id,
  label,
  title,
  description,
  summary,
  aside,
  children,
  width = 'band',
  content = 'wide',
  last = false,
  classes,
  ...props
}: PageSectionProps) {
  const slots = mergeSlots(pageSection({ last, width }), classes)
  const frameClass = { band: ' lx-band', frame: ' lx-frame', text: '' }[width]
  const contentClass = width === 'band' && content === 'wide' ? ' lx-wide' : ''
  return (
    <section
      {...props}
      aria-labelledby={id}
      data-recipe="page-section"
      data-width={width}
      data-slot="root"
      className={`${slots.root}${frameClass}`}
